SET ROLE talus_fn;
CREATE TABLE app.analytics_daily_snapshot(tenant_id uuid NOT NULL,metric_date date NOT NULL,total_revenue_cents bigint NOT NULL,fleet_utilization_bp integer NOT NULL CHECK(fleet_utilization_bp BETWEEN 0 AND 10000),active_trips_count integer NOT NULL,maintenance_blocks_count integer NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,metric_date),FOREIGN KEY(tenant_id) REFERENCES app.tenant(tenant_id));
CREATE OR REPLACE FUNCTION app.get_financial_summary(p_start timestamptz,p_end timestamptz) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE t uuid:=app.current_context_tenant_id();BEGIN PERFORM app.require_staff_role('staff');RETURN(SELECT jsonb_build_object('revenue_cents',COALESCE(sum(CASE WHEN a.account_type='revenue' AND p.direction='credit' THEN p.amount_cents WHEN a.account_type='revenue' THEN -p.amount_cents ELSE 0 END),0),'liability_cents',COALESCE(sum(CASE WHEN a.account_type='liability' AND p.direction='credit' THEN p.amount_cents WHEN a.account_type='liability' THEN -p.amount_cents ELSE 0 END),0),'expense_cents',COALESCE(sum(CASE WHEN a.account_type='expense' AND p.direction='debit' THEN p.amount_cents WHEN a.account_type='expense' THEN -p.amount_cents ELSE 0 END),0)) FROM app.ledger_posting p JOIN app.journal_entry j ON j.tenant_id=p.tenant_id AND j.journal_entry_id=p.journal_entry_id JOIN app.ledger_account a ON a.tenant_id=p.tenant_id AND a.ledger_account_id=p.ledger_account_id WHERE p.tenant_id=t AND j.occurred_at>=p_start AND j.occurred_at<p_end);END;$$;
CREATE OR REPLACE FUNCTION app.get_fleet_utilization(p_start timestamptz,p_end timestamptz) RETURNS TABLE(machine_id uuid,category_location_id uuid,utilization_bp integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=app,public AS $$ WITH w AS (SELECT tstzrange(p_start,p_end,'[)') r,GREATEST(0::bigint,EXTRACT(EPOCH FROM(p_end-p_start))::bigint) s), os AS (SELECT o.machine_id,SUM(EXTRACT(EPOCH FROM(upper(o.occupancy_range*w.r)-lower(o.occupancy_range*w.r)))::bigint) used FROM app.machine_occupancy o CROSS JOIN w WHERE o.tenant_id=app.current_context_tenant_id() AND o.occupancy_kind='rental' AND o.occupancy_range&&w.r GROUP BY o.machine_id) SELECT m.machine_id,m.category_location_id,CASE WHEN w.s=0 THEN 0 ELSE ((COALESCE(os.used,0)*10000)/w.s)::integer END FROM app.machine m CROSS JOIN w LEFT JOIN os ON os.machine_id=m.machine_id WHERE m.tenant_id=app.current_context_tenant_id(); $$;
ALTER TABLE app.analytics_daily_snapshot ENABLE ROW LEVEL SECURITY;ALTER TABLE app.analytics_daily_snapshot FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_context_policy ON app.analytics_daily_snapshot USING(tenant_id=app.current_context_tenant_id() AND app.context_is_valid()) WITH CHECK(tenant_id=app.current_context_tenant_id() AND app.context_is_valid());
REVOKE ALL ON app.analytics_daily_snapshot FROM PUBLIC,talus_staff,talus_api,talus_customer;
RESET ROLE;
